"use strict";
/* Extra animated lessons for the System Design Essentials, MERN Stack, MongoDB, PostgreSQL and Deployment guides.
   Same format as LESSONS in app.js. Actions: ['s',from,to,label,kind('r'|'x')], ['m',node,state], ['n',node,text], ['cut',a,b], ['heal',a,b]
   Map stage is 960×470; nodes are 140×60, so keep x in 90–870 and y in 70–410. */
window.EXTRA_LESSONS = [
/* ---------------- MERN Stack ---------------- */
{ id:"mernflow", group:"MERN Stack", title:"MERN request flow end to end", mode:"map",
  blurb:"Follow one product-list request through CDN, load balancer, Express middleware, Redis cache-aside and MongoDB.",
  nodes:[{id:"br",x:90,y:250,label:"Browser",sub:"React SPA",kind:"client"},{id:"cdn",x:320,y:90,label:"CDN",sub:"S3 + CloudFront",kind:"cdn"},
         {id:"lb",x:320,y:360,label:"Nginx / LB",sub:"TLS",kind:"lb"},{id:"api",x:580,y:360,label:"Express API",sub:"Node × 3",kind:"server"},
         {id:"redis",x:840,y:180,label:"Redis",sub:"cache",kind:"cache"},{id:"mongo",x:840,y:400,label:"MongoDB",sub:"replica set",kind:"db"}],
  edges:[["br","cdn"],["br","lb"],["lb","api"],["api","redis"],["api","mongo"]],
  steps:[
    {say:"The user opens the app. index.html and the hashed JS and CSS bundles come from the CDN edge, not from your servers, and can be cached for a year.", a:[["s","br","cdn","GET /app.3f9a.js"],["s","cdn","br","200 · edge cache hit","r"],["m","br","active"]]},
    {say:"React boots and calls the API. Nginx or a load balancer terminates TLS and spreads requests across the Node instances.", a:[["s","br","lb","GET /api/products?cat=shoes"],["s","lb","api","proxy → node-2"]]},
    {say:"Express runs its middleware chain in order: helmet, CORS, rate limit, auth (verify the JWT), validation, then the route handler.", a:[["m","api","active"],["n","api","helmet → cors → limit → auth → zod"]]},
    {say:"Cache-aside: the service checks Redis first.", a:[["s","api","redis","GET products:shoes:p1"],["s","redis","api","miss","r"]]},
    {say:"On a miss it queries MongoDB, which uses a compound index on {category, price}.", a:[["s","api","mongo","find({category:'shoes'})"],["s","mongo","api","20 docs · 4 ms","r"]]},
    {say:"The result is written to Redis with a TTL, so the next thousand requests skip the database.", a:[["s","api","redis","SET … EX 60"],["n","redis","TTL 60 s"]]},
    {say:"JSON goes back with Cache-Control headers. React Query caches it in the browser and the component re-renders.", a:[["m","api",null],["s","api","lb","200 · JSON","r"],["s","lb","br","200 · JSON","r"],["m","br","ok"]]},
    {say:"Node instances keep no session state (JWTs or sessions in Redis), so you scale by adding instances behind the load balancer.", a:[["n","api","stateless → scale out"],["m","api","ok"]]}
  ],
  takeaways:["Static assets come from the CDN; only API calls reach Node.","Middleware order matters: security and auth run before handlers.","Cache-aside with Redis absorbs read traffic; TTLs bound staleness.","Stateless Node instances scale horizontally behind a load balancer."],
  related:["mern-arch-reference-architecture","mern-arch-caching-layers","mern-node-express-middleware","mern-node-layered-architecture"] },

{ id:"nodeloop", group:"MERN Stack", title:"Node.js event loop", mode:"map",
  blurb:"How one JavaScript thread serves thousands of requests: the call stack, libuv, the thread pool, callback phases and microtasks.",
  nodes:[{id:"req",x:100,y:250,label:"Requests",sub:"HTTP",kind:"client"},{id:"stack",x:380,y:250,label:"Call stack",sub:"JS main thread",kind:"server"},
         {id:"micro",x:380,y:80,label:"Microtasks",sub:"nextTick · promises",kind:"queue"},{id:"os",x:640,y:90,label:"OS async I/O",sub:"epoll · kqueue",kind:"service"},
         {id:"pool",x:640,y:410,label:"libuv pool",sub:"fs · crypto · dns",kind:"worker"},{id:"cbq",x:860,y:250,label:"Callback queues",sub:"timers · poll · check",kind:"queue"}],
  edges:[["req","stack"],["stack","micro"],["stack","os"],["stack","pool"],["os","cbq"],["pool","cbq"],["cbq","stack"]],
  steps:[
    {say:"A request arrives. Node runs your handler on a single JavaScript thread, the call stack.", a:[["s","req","stack","GET /orders"],["m","stack","active"]]},
    {say:"The handler queries MongoDB. Network I/O goes to the operating system's async APIs, and the JS thread moves on instead of waiting.", a:[["s","stack","os","socket read (DB query)"],["n","stack","free for next request"]]},
    {say:"It also hashes a password with bcrypt. Work the OS can't do asynchronously (file system, crypto, DNS lookup) runs on libuv's thread pool, 4 threads by default.", a:[["s","stack","pool","bcrypt.hash()"],["n","pool","4 threads · UV_THREADPOOL_SIZE"],["m","pool","active"]]},
    {say:"Meanwhile other requests run on the same thread. This is how one Node process handles thousands of concurrent connections.", a:[["s","req","stack","GET /products"]]},
    {say:"The DB reply arrives and the hash finishes. Their callbacks wait in the event loop's queues.", par:true, a:[["s","os","cbq","DB result ready"],["s","pool","cbq","hash done"],["m","pool",null]]},
    {say:"The loop cycles through phases: timers, pending, poll (I/O), check (setImmediate), close. When the stack is empty it runs the next callback.", a:[["n","cbq","timers → poll → check → close"],["s","cbq","stack","run callback"]]},
    {say:"After each callback Node drains the microtask queue: process.nextTick first, then resolved promises. That is where your await continuations run.", a:[["s","stack","micro","await resolved"],["s","micro","stack","continue handler","r"]]},
    {say:"A synchronous loop over a million items, or JSON.parse on a 50 MB body, blocks the stack. Every other request waits and event loop lag spikes.", a:[["m","stack","bad"],["n","stack","blocked 800 ms"],["s","req","stack","GET /health","x"]]},
    {say:"The fix: move CPU work to worker threads or a job queue, stream large payloads, and alert on event loop lag.", a:[["m","stack","ok"],["n","stack","lag < 10 ms"]]}
  ],
  takeaways:["One JS thread plus async I/O gives high concurrency for I/O-bound work.","The libuv thread pool (default 4) handles fs, crypto and DNS lookups.","Microtasks (nextTick, promises) run before the loop moves to the next phase.","Never block the loop: offload CPU work and monitor event loop lag."],
  related:["mern-node-event-loop","mern-node-scaling","how-does-javascript-work"] },

{ id:"mernauth", group:"MERN Stack", title:"Access and refresh tokens", mode:"seq",
  blurb:"Short-lived access tokens, refresh tokens in httpOnly cookies, rotation, and catching a stolen refresh token.",
  lanes:[{id:"b",label:"Browser (React)"},{id:"api",label:"Express API"},{id:"db",label:"Token store"},{id:"x",label:"Attacker"}],
  steps:[
    {say:"The user logs in. The API checks the bcrypt password hash.", a:[["s","b","api","POST /login"],["s","api","db","verify password hash"],["s","db","api","user ok","r"]]},
    {say:"The API issues a 15-minute access token and a long-lived refresh token. The refresh token goes in an httpOnly, Secure, SameSite cookie that JavaScript cannot read.", a:[["s","api","db","save refresh family F1"],["s","api","b","access JWT + cookie rt1","r"],["n","b","access token in memory"]]},
    {say:"Each API call sends the access token in the Authorization header. The API verifies its signature without a database lookup.", a:[["s","b","api","GET /orders · Bearer JWT"],["s","api","b","200 · orders","r"]]},
    {say:"Fifteen minutes later the access token has expired.", a:[["s","b","api","GET /orders · expired JWT"],["s","api","b","401 token expired","x"]]},
    {say:"The app quietly calls /refresh. The browser attaches the cookie automatically.", a:[["s","b","api","POST /refresh · cookie rt1"],["s","api","db","rt1 valid? rotate"]]},
    {say:"Rotation: rt1 is marked used and replaced by rt2, along with a new access token. The original request is retried.", a:[["s","db","api","ok · rt1 now used","r"],["s","api","b","new JWT + cookie rt2","r"],["n","b","retry GET /orders ✓"]]},
    {say:"An attacker who stole rt1 replays it. It has already been used, so the API revokes the whole token family and the real user must sign in again.", a:[["s","x","api","POST /refresh · rt1","x"],["s","api","db","reuse! revoke family F1"],["n","api","reuse detected → revoke all"]]}
  ],
  takeaways:["Keep access tokens short-lived and in memory, not localStorage.","Store refresh tokens in httpOnly, Secure, SameSite cookies.","Rotate refresh tokens on every use and revoke the family on reuse.","Cookies need CSRF protection (SameSite plus a CSRF token or origin check) and CORS with credentials."],
  related:["mern-node-authentication","mern-node-api-security-rate-limiting","jwt-101-key-to-stateless-authentication","what's-the-difference-between-session-based-authentication-and-jwts"] },

{ id:"socketio", group:"MERN Stack", title:"Scaling Socket.IO with Redis", mode:"map",
  blurb:"Real-time messages across several Node servers: sticky sessions, rooms, the Redis adapter and reconnection.",
  nodes:[{id:"u1",x:90,y:120,label:"Alice",kind:"user"},{id:"u2",x:90,y:390,label:"Bob",kind:"user"},{id:"lb",x:310,y:250,label:"Load balancer",sub:"sticky sessions",kind:"lb"},
         {id:"n1",x:570,y:120,label:"Node 1",sub:"Socket.IO",kind:"server"},{id:"n2",x:570,y:390,label:"Node 2",sub:"Socket.IO",kind:"server"},
         {id:"redis",x:850,y:250,label:"Redis",sub:"pub/sub adapter",kind:"cache"},{id:"mongo",x:850,y:80,label:"MongoDB",sub:"messages",kind:"db"}],
  edges:[["u1","lb"],["u2","lb"],["lb","n1"],["lb","n2"],["n1","redis"],["n2","redis"],["n1","mongo"]],
  steps:[
    {say:"Alice connects with her JWT. Socket.IO can start on HTTP long-polling and upgrade to WebSocket, so sticky sessions keep her on one node.", a:[["s","u1","lb","connect + JWT"],["s","lb","n1","upgrade: websocket"],["n","n1","Alice in room:order-42"]]},
    {say:"Bob connects and lands on Node 2. Both join the room order-42.", a:[["s","u2","lb","connect + JWT"],["s","lb","n2","upgrade: websocket"],["n","n2","Bob in room:order-42"]]},
    {say:"Alice sends a message. Node 1 saves it to MongoDB first, so it survives disconnects.", a:[["s","u1","lb","chat: shipped yet?"],["s","lb","n1","chat"],["s","n1","mongo","insert message"]]},
    {say:"Problem: Node 1 only knows its own sockets. Bob is connected to Node 2, so without an adapter he never sees the message.", a:[["n","n1","room emit → local sockets only"],["m","n2","warn"]]},
    {say:"The Redis adapter publishes each room broadcast. Every node subscribes and delivers it to its own room members.", a:[["s","n1","redis","PUBLISH room:order-42"],["s","redis","n2","message"],["m","n2",null]]},
    {say:"Node 2 pushes the message down Bob's open WebSocket within milliseconds, with no polling.", a:[["s","n2","lb","emit chat"],["s","lb","u2","shipped yet?","r"],["m","u2","ok"]]},
    {say:"Node 2 dies. Bob's client reconnects automatically, lands on Node 1, rejoins the room, and fetches anything he missed from MongoDB.", a:[["m","n2","bad"],["n","n2","down"],["s","u2","lb","reconnect"],["s","lb","n1","rejoin room"],["s","n1","mongo","messages after id 981"]]}
  ],
  takeaways:["Long-polling fallback needs sticky sessions at the load balancer.","Rooms are per process; the Redis adapter fans broadcasts out across nodes.","Persist messages before emitting, so clients can catch up after reconnecting.","Authenticate on connect and authorize room joins on the server."],
  related:["mern-arch-realtime-socketio","shortlong-polling-sse-websocket","build-a-simple-chat-application"] },

{ id:"bullmq", group:"MERN Stack", title:"Background jobs with BullMQ", mode:"map",
  blurb:"Take slow work out of the request: queue it in Redis, process it in workers, retry with backoff, and keep it idempotent.",
  nodes:[{id:"c",x:90,y:250,label:"React app",kind:"client"},{id:"api",x:320,y:250,label:"Express API",kind:"server"},{id:"db",x:320,y:420,label:"MongoDB",kind:"db"},
         {id:"q",x:580,y:250,label:"Redis queue",sub:"BullMQ: emails",kind:"queue"},{id:"w1",x:850,y:110,label:"Worker 1",kind:"worker"},
         {id:"w2",x:850,y:390,label:"Worker 2",kind:"worker"},{id:"smtp",x:580,y:80,label:"Email provider",kind:"service"}],
  edges:[["c","api"],["api","db"],["api","q"],["q","w1"],["q","w2"],["w1","smtp"],["w2","smtp"]],
  steps:[
    {say:"A user places an order. Sending the confirmation email and building the PDF invoice are slow and can fail.", a:[["s","c","api","POST /orders"],["s","api","db","insert order"]]},
    {say:"The API enqueues a job with a deterministic jobId instead of doing the work inline, and responds in about 30 ms.", a:[["s","api","q","add confirm {orderId:42}"],["s","api","c","201 Created · 30 ms","r"],["n","q","waiting: 1"]]},
    {say:"Workers are separate Node processes. They pull jobs from Redis, and each job goes to exactly one worker.", a:[["s","q","w1","job confirm:42"],["m","w1","active"],["n","q","active: 1"]]},
    {say:"The email provider times out. The job fails and is retried with exponential backoff: 1 s, 2 s, 4 s and so on.", a:[["s","w1","smtp","send email"],["s","smtp","w1","timeout","x"],["m","w1","warn"],["s","w1","q","failed · retry in 2 s","x"],["n","q","delayed: 1"]]},
    {say:"Worker 2 picks up the retry and succeeds. The handler checks emailSentAt first, so a duplicate run can't send two emails.", a:[["m","w1",null],["s","q","w2","confirm:42 attempt 2"],["s","w2","smtp","send email"],["s","smtp","w2","250 OK","r"],["m","w2","ok"],["n","q","completed: 1"]]},
    {say:"Jobs that use up all their attempts stay in the failed set, which works as a dead-letter queue for alerts and manual replay. Workers scale separately from the API.", a:[["n","w2","scale workers separately"]]}
  ],
  takeaways:["Respond fast and push slow or flaky work to a queue.","Retries with exponential backoff absorb transient failures.","Jobs can run more than once, so make handlers idempotent.","Monitor the failed set and scale workers independently."],
  related:["mern-node-background-jobs-bullmq","mern-node-file-uploads-s3"] },

{ id:"s3upload", group:"MERN Stack", title:"Direct-to-S3 uploads", mode:"seq",
  blurb:"Presigned URLs let the browser upload straight to S3 while the API only grants permission and processing happens asynchronously.",
  lanes:[{id:"b",label:"Browser"},{id:"api",label:"Express API"},{id:"s3",label:"S3 bucket"},{id:"w",label:"Worker"}],
  steps:[
    {say:"Streaming files through Express ties up Node memory and bandwidth. Instead, the browser asks the API for permission to upload.", a:[["s","b","api","POST /uploads · image/png 2 MB"]]},
    {say:"The API checks auth, file type and size, then signs a short-lived URL with its AWS credentials. No file bytes touch the API.", a:[["n","api","validate · key u7/uuid.png"],["s","api","b","presigned PUT URL (5 min)","r"]]},
    {say:"The browser uploads the file directly to S3.", a:[["s","b","s3","PUT u7/uuid.png"],["s","s3","b","200 OK","r"]]},
    {say:"S3 emits an ObjectCreated event, which triggers a processing job.", a:[["s","s3","w","event: ObjectCreated"]]},
    {say:"The worker checks the real file type, resizes the image, writes thumbnails, and marks the record ready in MongoDB.", a:[["s","w","s3","GET original"],["s","w","s3","PUT thumbnails 200 and 800"],["n","w","status = ready"]]},
    {say:"The app serves the images through CloudFront with long cache lifetimes.", a:[["s","b","api","GET /me"],["s","api","b","avatar on cdn.example.com","r"]]}
  ],
  takeaways:["Presigned URLs keep large uploads off your Node servers.","Validate type and size when signing and again after upload.","Process uploads asynchronously with events and workers.","Serve user content from a CDN, ideally on a separate domain."],
  related:["mern-node-file-uploads-s3","mern-node-background-jobs-bullmq"] },

/* ---------------- MongoDB ---------------- */
{ id:"mongors", group:"MongoDB", title:"MongoDB replica set and failover", mode:"map",
  blurb:"Majority writes, the oplog, read preferences, and what happens when the primary dies.",
  nodes:[{id:"app",x:110,y:250,label:"Node app",sub:"MongoDB driver",kind:"server"},{id:"p",x:480,y:250,label:"Primary",kind:"db"},
         {id:"s1",x:830,y:110,label:"Secondary 1",kind:"db"},{id:"s2",x:830,y:390,label:"Secondary 2",kind:"db"}],
  edges:[["app","p"],["p","s1"],["p","s2"],["s1","s2"],["app","s1"],["app","s2"]],
  steps:[
    {say:"All writes go to the primary. With writeConcern w: 'majority', the driver waits until 2 of the 3 members have the write.", a:[["s","app","p","insertOne · w: majority"],["n","p","oplog #501"]]},
    {say:"Secondaries tail the primary's oplog and apply each entry.", par:true, a:[["s","p","s1","oplog #501"],["s","p","s2","oplog #501"],["n","s1","applied #501"],["n","s2","applied #501"]]},
    {say:"Once one secondary acknowledges, a majority has the write and it can't be rolled back. The driver reports success.", a:[["s","s1","p","ack #501","r"],["s","p","app","ok (majority)","r"],["m","app","ok"]]},
    {say:"With readPreference secondaryPreferred, reads are spread across members but may be slightly stale. Read your own writes from the primary or use causally consistent sessions.", a:[["m","app",null],["s","app","s2","find · secondaryPreferred"],["s","s2","app","maybe stale","r"]]},
    {say:"The primary crashes. Members stop receiving heartbeats, and after the election timeout (10 s by default) a secondary calls an election.", a:[["m","p","bad"],["n","p","down"],["s","s1","s2","vote for me? term 8"],["s","s2","s1","yes","r"]]},
    {say:"Secondary 1 becomes primary. The driver finds the new primary and retryable writes resend the in-flight insert. The whole blip usually takes around 10–12 seconds.", a:[["m","s1","ok"],["n","s1","PRIMARY · term 8"],["s","app","s1","retry insertOne"],["s","s1","app","ok","r"]]},
    {say:"When the old primary rejoins, any writes that only it had (acknowledged with w: 1) are rolled back. That is why w: 'majority' is the default.", a:[["m","p","warn"],["n","p","rejoins as secondary · rollback"]]}
  ],
  takeaways:["A replica set gives high availability and read scaling, not write scaling.","w: 'majority' writes survive failover; w: 1 writes can be rolled back.","Reads from secondaries can be stale; choose read preference per query.","Retryable writes and reads make most failovers invisible to a Node app."],
  related:["mongodb-replica-sets","mongodb-transactions-and-consistency","read-replica-pattern"] },

{ id:"mongoshard", group:"MongoDB", title:"MongoDB sharding", mode:"map",
  blurb:"How mongos routes queries by shard key, why scatter-gather hurts, and how bad shard keys create hot shards.",
  nodes:[{id:"app",x:100,y:250,label:"Node app",kind:"server"},{id:"ms",x:340,y:250,label:"mongos",sub:"query router",kind:"router"},
         {id:"cfg",x:340,y:80,label:"Config servers",sub:"chunk map",kind:"db"},{id:"sa",x:730,y:90,label:"Shard A",sub:"custId < 3000",kind:"db"},
         {id:"sb",x:730,y:250,label:"Shard B",sub:"3000 – 7000",kind:"db"},{id:"sc",x:730,y:410,label:"Shard C",sub:"≥ 7000",kind:"db"}],
  edges:[["app","ms"],["ms","cfg"],["ms","sa"],["ms","sb"],["ms","sc"],["sb","sc"]],
  steps:[
    {say:"The orders collection is sharded on {customerId: 1}. The app connects to mongos as if it were a normal mongod.", a:[["s","app","ms","find {customerId: 4521}"]]},
    {say:"mongos checks its cached routing table, which comes from the config servers, to see which chunk range owns 4521.", a:[["s","ms","cfg","routing table?"],["s","cfg","ms","3000–7000 → Shard B","r"]]},
    {say:"Targeted query: only Shard B is asked. This is what scales, because adding shards adds capacity.", a:[["s","ms","sb","customerId 4521"],["s","sb","ms","12 orders","r"],["s","ms","app","12 orders","r"],["m","sb","ok"]]},
    {say:"A query without the shard key can't be routed. mongos sends it to every shard and merges the results, so it is only as fast as the slowest shard.", par:true, a:[["m","sb",null],["s","ms","sa","status: late"],["s","ms","sb","status: late"],["s","ms","sc","status: late"],["n","ms","scatter-gather"]]},
    {say:"Shard B grows faster than the others. The balancer migrates a chunk range to even out data size.", a:[["m","sb","warn"],["n","sb","2× data of others"],["s","sb","sc","migrate 5000–7000"],["n","sc","now ≥ 5000"],["m","sb",null]]},
    {say:"Bad key: a monotonically increasing key like createdAt or an ObjectId sends every insert to the last chunk, creating one hot shard. Use a hashed or compound key with high cardinality.", a:[["s","app","ms","insert {createdAt: now}"],["s","ms","sc","every insert","x"],["m","sc","bad"],["n","sc","hot shard"]]}
  ],
  takeaways:["Sharding scales writes and storage; the shard key decides everything.","Queries that include the shard key are targeted; others scatter-gather.","Avoid low-cardinality and monotonically increasing shard keys.","Shard only after indexing, scaling up and caching stop being enough."],
  related:["mongodb-sharding-shard-keys","mongodb-scaling-roadmap","mongodb-indexes-and-explain"] },

{ id:"mongoagg", group:"MongoDB", title:"MongoDB aggregation pipeline", mode:"map",
  blurb:"Documents stream through stages. Watch how stage order turns a million-document scan into ten lookups.",
  nodes:[{id:"coll",x:90,y:250,label:"orders",sub:"1M docs",kind:"db"},{id:"match",x:270,y:250,label:"$match",sub:"uses index",kind:"service"},
         {id:"group",x:450,y:250,label:"$group",sub:"by customer",kind:"service"},{id:"sort",x:630,y:250,label:"$sort + $limit",sub:"top 10",kind:"service"},
         {id:"lookup",x:830,y:250,label:"$lookup",sub:"join users",kind:"service"},{id:"users",x:830,y:420,label:"users",kind:"db"},{id:"out",x:830,y:80,label:"Result",kind:"client"}],
  edges:[["coll","match"],["match","group"],["group","sort"],["sort","lookup"],["lookup","users"],["lookup","out"]],
  steps:[
    {say:"Goal: the top 10 customers by revenue last month. The pipeline streams documents through stages, one after another.", a:[["n","coll","1,000,000 orders"]]},
    {say:"$match comes first and uses an index, so only last month's paid orders are read.", a:[["s","coll","match","paid · date ≥ Oct 1"],["n","match","IXSCAN → 40,000 docs"]]},
    {say:"$group sums revenue per customer. Blocking stages have a 100 MB memory limit and spill to disk when allowDiskUse is on.", a:[["s","match","group","40,000 docs"],["n","group","{_id: custId, total: $sum}"]]},
    {say:"$sort followed by $limit becomes a top-k sort that keeps only 10 documents in memory.", a:[["s","group","sort","8,200 groups"],["n","sort","top-k = 10"]]},
    {say:"$lookup after the limit joins 10 customers, not 40,000 orders. Stage order is the biggest performance lever.", a:[["s","sort","lookup","10 docs"],["s","lookup","users","_id in 10 ids"],["s","users","lookup","10 users","r"]]},
    {say:"The result returns. If this runs on every page view, precompute it into a summary collection with $merge on a schedule.", a:[["s","lookup","out","top 10 + names","r"],["m","out","ok"],["n","out","or $merge nightly"]]}
  ],
  takeaways:["Put $match (and $project) early so indexes apply and fewer docs flow on.","$sort plus $limit is optimized into a top-k sort.","$lookup after reducing the data, not before.","Precompute expensive aggregations with $merge for hot dashboards."],
  related:["mongodb-aggregation-pipeline","mongodb-indexes-and-explain","mongodb-performance-tuning"] },

/* ---------------- PostgreSQL ---------------- */
{ id:"pgmvcc", group:"PostgreSQL", title:"Postgres MVCC and VACUUM", mode:"seq",
  blurb:"Updates create new row versions, readers keep their snapshot, and VACUUM cleans up, unless a long transaction gets in the way.",
  lanes:[{id:"a",label:"Txn A (report)"},{id:"b",label:"Txn B (writer)"},{id:"t",label:"Table heap"},{id:"v",label:"Autovacuum"}],
  steps:[
    {say:"Row id=1 has price 10, stored as tuple version v1 created by transaction 100.", a:[["n","t","v1 price=10 · xmin 100"]]},
    {say:"Transaction A starts a long report and takes a snapshot.", a:[["s","a","t","BEGIN · SELECT price"],["s","t","a","10 (v1)","r"]]},
    {say:"Transaction B updates the price. Postgres does not overwrite the row: it writes a new tuple v2 and marks v1 as deleted by transaction 205.", a:[["s","b","t","UPDATE price = 12"],["n","t","v1 xmax 205 · v2 price=12"],["s","b","t","COMMIT"]]},
    {say:"Readers never block writers. A's snapshot still sees v1, and B's change is invisible to it.", a:[["s","a","t","SELECT price"],["s","t","a","10 (snapshot)","r"]]},
    {say:"Any new transaction sees v2.", a:[["s","b","t","SELECT price"],["s","t","b","12 (v2)","r"]]},
    {say:"Autovacuum wants to reclaim v1, but A's snapshot could still need it, so it must keep it. Long-running transactions cause table bloat.", a:[["s","v","t","can v1 go?"],["n","v","v1 still visible to A → keep"]]},
    {say:"A commits. v1 is now dead to everyone, so vacuum marks its space reusable and updates the visibility map.", a:[["s","a","t","COMMIT"],["s","v","t","reclaim v1"],["n","t","v2 only · space reused"]]}
  ],
  takeaways:["An UPDATE is an insert of a new version plus marking the old one dead.","Snapshots give consistent reads without read locks.","VACUUM reclaims dead tuples; autovacuum must keep up with write volume.","Long or idle-in-transaction sessions block cleanup and cause bloat."],
  related:["postgres-how-it-works","postgres-transactions-isolation"] },

{ id:"pgpool", group:"PostgreSQL", title:"Connection pooling with PgBouncer", mode:"map",
  blurb:"Why many Node pods can exhaust Postgres connections, and how transaction pooling multiplexes them.",
  nodes:[{id:"a1",x:110,y:90,label:"Node pod 1",sub:"pool 20",kind:"server"},{id:"a2",x:110,y:250,label:"Node pod 2",sub:"pool 20",kind:"server"},
         {id:"a3",x:110,y:410,label:"Node pod 3",sub:"pool 20",kind:"server"},{id:"pb",x:480,y:250,label:"PgBouncer",sub:"transaction mode",kind:"pool"},
         {id:"pg",x:840,y:250,label:"PostgreSQL",sub:"max_connections 100",kind:"db"}],
  edges:[["a1","pb"],["a2","pb"],["a3","pb"],["pb","pg"]],
  steps:[
    {say:"Each Postgres connection is a separate server process using several MB of memory. Connecting is slow and max_connections is usually in the low hundreds.", a:[["n","pg","1 process per connection"]]},
    {say:"Without a pooler, 30 Node pods with a pool size of 20 need 600 connections. Postgres refuses the extra ones and pods start failing.", a:[["n","a1","20 conns"],["n","a2","20 conns"],["n","a3","20 conns"],["n","pg","600 needed > 100"],["m","pg","bad"]]},
    {say:"PgBouncer accepts thousands of cheap client connections and multiplexes them onto a small pool of real server connections.", par:true, a:[["m","pg",null],["s","a1","pb","BEGIN …"],["s","a2","pb","SELECT …"],["s","a3","pb","UPDATE …"],["n","pb","1,000 clients → 40 server conns"]]},
    {say:"In transaction mode a server connection is lent for one transaction and returned at COMMIT. Most client connections sit idle, so 40 server connections can serve everyone.", a:[["s","pb","pg","txn on server conn #7"],["s","pg","pb","COMMIT","r"],["n","pg","40 conns · healthy"],["m","pg","ok"]]},
    {say:"Caveat: session state doesn't carry over. SET, session advisory locks, LISTEN and, before PgBouncer 1.21, named prepared statements break. Keep state inside the transaction.", a:[["m","pb","warn"],["n","pb","no session state"]]},
    {say:"Serverless functions are the extreme case, because every invocation can open connections. Put PgBouncer or RDS Proxy in front.", a:[["m","pb","ok"],["n","pb","or RDS Proxy"]]}
  ],
  takeaways:["Postgres connections are expensive; size pools from the database side down.","Total connections = pods × pool size; it grows silently as you scale out.","Transaction-mode pooling multiplexes many clients onto few connections.","Avoid session-level features behind a transaction pooler."],
  related:["postgres-connection-pooling","postgres-how-it-works","postgres-scaling-roadmap"] },

{ id:"pgmigrate", group:"PostgreSQL", title:"Zero-downtime schema migration", mode:"seq",
  blurb:"Rename a column with no downtime using expand and contract, safe locks, batched backfills and NOT VALID constraints.",
  lanes:[{id:"v1",label:"App v1"},{id:"v2",label:"App v2"},{id:"m",label:"Migration"},{id:"db",label:"PostgreSQL"}],
  steps:[
    {say:"Goal: rename users.name to full_name without downtime. A plain RENAME would break v1 the moment it runs.", a:[["n","db","users(name)"],["s","v1","db","reads and writes name"]]},
    {say:"Expand: add the new nullable column. This is a quick metadata change, and lock_timeout stops it from queueing behind a long query and blocking everyone.", a:[["s","m","db","SET lock_timeout = '2s'"],["s","m","db","ADD COLUMN full_name text"]]},
    {say:"Deploy v2, which writes both columns but still reads name. v1 and v2 run side by side during the rollout.", a:[["s","v2","db","write name + full_name"],["s","v1","db","write name"]]},
    {say:"Backfill old rows in small batches to avoid long locks and replication lag.", a:[["s","m","db","UPDATE … id 1–5000"],["n","db","batch 1 of 200 …"]]},
    {say:"Add constraints safely: first NOT VALID, then VALIDATE, which doesn't block writes. Build indexes with CREATE INDEX CONCURRENTLY.", a:[["s","m","db","ADD CONSTRAINT … NOT VALID"],["s","m","db","VALIDATE CONSTRAINT"]]},
    {say:"Deploy v3, which reads and writes only full_name. v1 is gone.", a:[["n","v1","retired"],["s","v2","db","read full_name"]]},
    {say:"Contract: once nothing uses name, drop it in a later release.", a:[["s","m","db","DROP COLUMN name"],["n","db","users(full_name)"]]}
  ],
  takeaways:["Every schema change must work with both the old and new app versions.","Expand → migrate data → switch reads → contract, across separate deploys.","Use lock_timeout, CONCURRENTLY and NOT VALID to avoid long locks.","Backfill in batches and watch replication lag."],
  related:["postgres-nodejs-zero-downtime-migrations","deploy-zero-downtime-deployments"] },

/* ---------------- Deployment ---------------- */
{ id:"deploys", group:"Deployment", title:"Zero-downtime deployments", mode:"map",
  blurb:"Rolling, blue-green and canary releases compared. Switch between them to see how traffic moves from v1 to v2.",
  nodes:[{id:"users",x:90,y:250,label:"Users",kind:"user"},{id:"lb",x:330,y:250,label:"Load balancer",kind:"lb"},
         {id:"blue",x:620,y:110,label:"Blue · v1",sub:"3 instances",kind:"server"},{id:"green",x:620,y:390,label:"Green · v2",sub:"3 instances",kind:"server"},
         {id:"db",x:870,y:250,label:"Database",kind:"db"}],
  edges:[["users","lb"],["lb","blue"],["lb","green"],["blue","db"],["green","db"]],
  variants:[
    {name:"Rolling", steps:[
      {say:"All traffic goes to v1.", a:[["s","users","lb","requests"],["s","lb","blue","100%"],["n","blue","v1 v1 v1"]]},
      {say:"One v2 instance starts (maxSurge 1). It gets no traffic until its readiness check passes.", a:[["m","green","active"],["n","green","v2 starting…"]]},
      {say:"It is ready, so it joins the pool. One v1 instance is drained: it is removed from the load balancer, finishes in-flight requests on SIGTERM, then exits.", a:[["m","green","ok"],["n","green","v2 ready"],["s","lb","green","share of traffic"],["n","blue","v1 v1 · 1 draining"]]},
      {say:"This repeats until every instance runs v2. Both versions serve traffic at the same time, so the API and database schema must work with both.", a:[["n","blue","—"],["n","green","v2 v2 v2"],["s","lb","green","100%"],["n","db","schema fits v1 and v2"]]}
    ]},
    {name:"Blue-green", steps:[
      {say:"Blue (v1) is live.", a:[["s","users","lb","requests"],["s","lb","blue","100% → v1"],["n","blue","live"]]},
      {say:"v2 is deployed to an identical, idle Green environment and smoke-tested privately.", a:[["n","green","v2 · smoke tests ✓"],["m","green","ok"]]},
      {say:"Switch: the load balancer (or DNS) moves all traffic to Green at once.", a:[["s","lb","green","100% → v2"],["n","blue","idle · kept warm"],["n","lb","switched"]]},
      {say:"If a problem appears, switch back immediately, because Blue is still running v1. The cost is double capacity during the release.", a:[["m","green","bad"],["s","lb","blue","rollback → v1","x"],["n","lb","switched back"]]}
    ]},
    {name:"Canary", steps:[
      {say:"v1 serves everyone.", a:[["s","users","lb","requests"],["s","lb","blue","100% → v1"]]},
      {say:"5% of traffic goes to v2, the canary.", a:[["s","lb","green","5%"],["n","green","canary · 5%"],["m","green","active"]]},
      {say:"Its error rate and p99 latency are compared automatically against v1.", a:[["n","green","errors 0.1% · p99 180 ms ✓"],["m","green","ok"]]},
      {say:"If it stays healthy, traffic ramps to 25%, 50% and 100%. If not, it rolls back automatically, and only 5% of users were affected.", a:[["s","lb","green","25% → 50% → 100%"],["n","blue","scaled down"]]}
    ]}
  ],
  takeaways:["Rolling is the default and cheapest, but mixes versions during the rollout.","Blue-green gives instant cutover and rollback at the cost of double capacity.","Canary limits the blast radius and relies on good metrics.","All of them need readiness checks, connection draining and backward-compatible schemas."],
  related:["deploy-zero-downtime-deployments","deploy-kubernetes-for-nodejs-apps","kubernetes-deployment-strategies","top-5-most-used-deployment-strategies"] },

{ id:"k8s", group:"Deployment", title:"Kubernetes probes and autoscaling", mode:"map",
  blurb:"Readiness and liveness probes, self-healing, the Horizontal Pod Autoscaler, and graceful shutdown for Node pods.",
  nodes:[{id:"user",x:90,y:250,label:"Users",kind:"user"},{id:"ing",x:290,y:250,label:"Ingress",kind:"lb"},{id:"svc",x:510,y:250,label:"Service",sub:"app: api",kind:"router"},
         {id:"hpa",x:510,y:80,label:"HPA",sub:"target CPU 70%",kind:"service"},{id:"p1",x:800,y:90,label:"Pod 1",sub:"Node API",kind:"server"},
         {id:"p2",x:800,y:250,label:"Pod 2",sub:"Node API",kind:"server"},{id:"p3",x:800,y:410,label:"Pod 3",sub:"Node API",kind:"server"}],
  edges:[["user","ing"],["ing","svc"],["svc","p1"],["svc","p2"],["svc","p3"],["hpa","svc"]],
  steps:[
    {say:"Traffic enters through the Ingress, and the Service load-balances across pods that are Ready.", a:[["s","user","ing","GET /api/orders"],["s","ing","svc","route"],["s","svc","p1","→ pod 1"]]},
    {say:"Readiness probe: Pod 2 is still connecting to MongoDB, so /ready fails. It receives no traffic but is not restarted.", a:[["m","p2","warn"],["n","p2","readiness ✗ · no traffic"]]},
    {say:"Liveness probe: Pod 3's process is stuck, and /health times out three times in a row. The kubelet restarts the container.", a:[["m","p3","bad"],["n","p3","liveness ✗ → restart"]]},
    {say:"Self-healing: the new container starts, its probes pass, and the Service adds it back. Pod 2 finishes connecting and becomes ready too.", a:[["m","p3","ok"],["n","p3","restarted · ready"],["m","p2","ok"],["n","p2","ready"]]},
    {say:"Load rises. The HPA sees average CPU at 90% against a 70% target and adds replicas. This only works if pods set CPU requests.", a:[["m","hpa","active"],["n","hpa","90% > 70% → 3 to 5 pods"]]},
    {say:"On scale-down or deploy, a pod gets SIGTERM. It is removed from the endpoints, a preStop sleep lets the change propagate, and Node calls server.close() to finish in-flight requests before exiting.", a:[["m","hpa",null],["m","p1","warn"],["n","p1","SIGTERM → drain → exit"]]}
  ],
  takeaways:["Readiness controls traffic; liveness controls restarts. Don't make them the same check.","Never make liveness depend on the database, or one DB blip restarts every pod.","Set resource requests so the scheduler and HPA can do their jobs.","Handle SIGTERM: stop accepting, drain, close DB connections, exit."],
  related:["deploy-kubernetes-for-nodejs-apps","mern-node-scaling","what-is-k8s-kubernetes","top-4-kubernetes-service-types-in-one-diagram"] },

{ id:"awsmern", group:"Deployment", title:"MERN on AWS", mode:"map",
  blurb:"A production layout: Route 53, CloudFront and S3 for React, an ALB and ECS Fargate for Express, ElastiCache and MongoDB Atlas in private networks.",
  nodes:[{id:"user",x:90,y:250,label:"User",kind:"user"},{id:"r53",x:290,y:80,label:"Route 53",kind:"dns"},{id:"cf",x:290,y:420,label:"CloudFront",sub:"+ S3 (React)",kind:"cdn"},
         {id:"alb",x:490,y:250,label:"ALB",sub:"TLS via ACM",kind:"lb"},{id:"ecs",x:690,y:250,label:"ECS Fargate",sub:"Express tasks",kind:"server"},
         {id:"redis",x:870,y:90,label:"ElastiCache",sub:"Redis",kind:"cache"},{id:"db",x:870,y:410,label:"MongoDB Atlas",sub:"private link",kind:"db"}],
  edges:[["user","r53"],["user","cf"],["user","alb"],["alb","ecs"],["ecs","redis"],["ecs","db"]],
  steps:[
    {say:"Route 53 resolves app.example.com to CloudFront and api.example.com to the load balancer.", a:[["s","user","r53","app.example.com?"],["s","r53","user","CloudFront · ALB","r"]]},
    {say:"The React build sits in a private S3 bucket served by CloudFront at the edge, with hashed assets cached for a year.", a:[["s","user","cf","GET /"],["s","cf","user","index.html + bundles","r"]]},
    {say:"API calls reach the Application Load Balancer in public subnets. It terminates TLS with an ACM certificate and health-checks the tasks.", a:[["s","user","alb","GET /api/cart"],["n","alb","public subnets"]]},
    {say:"Fargate tasks run the Express image from ECR in private subnets. Secrets are injected from Secrets Manager at start-up, and tasks auto-scale on CPU or request count.", a:[["s","alb","ecs","→ task 2 of 4"],["n","ecs","private subnets · auto scaling"]]},
    {say:"Sessions and cache live in ElastiCache. Data lives in MongoDB Atlas, reached over PrivateLink or VPC peering, with no public database endpoint.", a:[["s","ecs","redis","GET session"],["s","ecs","db","find cart"],["s","db","ecs","cart","r"]]},
    {say:"Security groups chain together: the ALB accepts 443 from the internet, tasks accept traffic only from the ALB, and databases only from the tasks.", a:[["n","db","SG: from tasks only"],["m","db","ok"]]},
    {say:"The response goes back. CloudWatch or OpenTelemetry collect logs, metrics and traces at each hop.", a:[["s","ecs","alb","200","r"],["s","alb","user","cart JSON","r"],["m","user","ok"]]}
  ],
  takeaways:["Serve the React app from S3 and CloudFront; only the API runs on compute.","Keep tasks and databases in private subnets behind security groups.","Managed services (Fargate, ElastiCache, Atlas or RDS) cut ops work.","Inject secrets at runtime; never bake them into images or bundles."],
  related:["deploy-mern-on-aws-reference-architecture","deploy-where-to-deploy-mern-hosting-options","deploy-managed-databases-production","deploy-configuration-secrets-management"] },

/* ---------------- System Design Essentials ---------------- */
{ id:"ratelimit", group:"System Design Essentials", title:"Rate limiting: token bucket vs sliding window", mode:"map",
  blurb:"How a gateway limiter uses Redis to allow bursts, refill tokens, reject with 429, and smooth the fixed-window boundary burst.",
  nodes:[{id:"cl",x:100,y:250,label:"Client",sub:"api key k1",kind:"client"},{id:"gw",x:400,y:250,label:"API gateway",sub:"rate limiter",kind:"gateway"},
         {id:"redis",x:400,y:80,label:"Redis",sub:"shared counters",kind:"cache"},{id:"api",x:800,y:250,label:"API",sub:"app servers",kind:"server"}],
  edges:[["cl","gw"],["gw","redis"],["gw","api"]],
  steps:[
    {say:"Every request passes the limiter in the gateway. The state lives in Redis, so all gateway instances share one count per client.", a:[["s","cl","gw","GET /search"],["m","gw","active"],["n","redis","bucket k1 · 10/10 tokens"]]},
    {say:"Token bucket: the bucket holds up to 10 tokens and refills at 5 per second. Each request takes one token.", a:[["s","gw","redis","take 1 token"],["s","redis","gw","ok · 9 left","r"],["s","gw","api","forward"],["n","redis","9/10 · +5 per s"]]},
    {say:"A burst of requests arrives at once. Because the bucket was full, the burst is allowed up to its capacity: bursts are a feature, not a bug.", par:true, a:[["s","cl","gw","× 9 in 100 ms"],["s","gw","api","forward × 9"],["n","redis","0/10 tokens"]]},
    {say:"The bucket is empty. The next request is rejected immediately with 429 Too Many Requests and a Retry-After header telling the client when a token will be back.", a:[["s","cl","gw","GET /search"],["s","gw","redis","take 1 token"],["s","redis","gw","empty","x"],["m","gw","bad"],["s","gw","cl","429 · Retry-After: 1","x"]]},
    {say:"Tokens refill continuously based on elapsed time. The limiter computes the refill lazily on each call instead of running a timer.", a:[["m","gw","active"],["n","redis","+5 after 1 s → 5/10"],["s","cl","gw","retry after 1 s"],["s","gw","api","forward"]]},
    {say:"Fixed windows have a flaw: 100 requests at 12:00:59 and 100 more at 12:01:00 both pass, so 200 hit the API in two seconds against a 100-per-minute limit.", a:[["m","api","warn"],["n","api","boundary burst: 200 in 2 s"]]},
    {say:"A sliding-window counter fixes this: weight the previous window by how much of it still overlaps. 15 s into the new window, count = 80 × 75% + 30 = 90.", a:[["m","api",null],["s","gw","redis","prev 80 · curr 30 · 25% in"],["s","redis","gw","weighted 90 < 100 · allow","r"],["n","gw","smooth, O(1) memory"]]},
    {say:"Read-then-write from many gateways races. Run the check-and-decrement as one Lua script (EVALSHA), which Redis executes atomically.", a:[["s","gw","redis","EVALSHA limiter.lua"],["n","redis","atomic check + decrement"],["m","redis","ok"]]},
    {say:"Allowed requests carry RateLimit-Remaining headers so well-behaved clients can slow down before they ever see a 429.", a:[["s","api","gw","200","r"],["s","gw","cl","200 · RateLimit-Remaining: 4","r"],["m","gw","ok"],["m","cl","ok"]]}
  ],
  takeaways:["Token bucket allows bursts up to capacity and enforces an average refill rate.","Fixed windows let up to 2× the limit through at window boundaries; sliding windows smooth that out.","Keep limiter state in Redis and update it atomically with a Lua script.","Reject with 429 plus Retry-After, and expose remaining quota in headers."],
  related:["sd-design-distributed-rate-limiter","mern-node-api-security-rate-limiting"] },

{ id:"circuit", group:"System Design Essentials", title:"Circuit breaker states", mode:"map",
  blurb:"Closed, open and half-open: how a breaker stops a flaky dependency from dragging your service down, plus retries with backoff and jitter.",
  nodes:[{id:"cl",x:100,y:250,label:"Callers",sub:"user traffic",kind:"user"},{id:"svc",x:340,y:250,label:"Checkout",sub:"service",kind:"service"},
         {id:"cb",x:590,y:250,label:"Circuit breaker",sub:"closed",kind:"router"},{id:"dep",x:850,y:250,label:"Pricing API",sub:"flaky dependency",kind:"service"},
         {id:"fb",x:590,y:410,label:"Fallback",sub:"cached prices",kind:"cache"}],
  edges:[["cl","svc"],["svc","cb"],["cb","dep"],["cb","fb"]],
  steps:[
    {say:"Closed state: the breaker lets every call through to the dependency and counts the results over a rolling window.", a:[["s","cl","svc","POST /checkout"],["s","svc","cb","getPrice()"],["s","cb","dep","call"],["s","dep","cb","200 · 40 ms","r"],["m","cb","ok"],["n","cb","CLOSED · 0% errors"]]},
    {say:"Transient failure: retry with exponential backoff and jitter (100 ms, 200 ms, 400 ms, each randomised) so thousands of clients don't retry in lockstep.", a:[["s","cb","dep","call"],["s","dep","cb","503","x"],["n","svc","retry in 100 ms ± jitter"],["s","cb","dep","retry 1"],["s","dep","cb","200","r"]]},
    {say:"The dependency degrades badly. Calls time out after 2 s, threads pile up waiting, and the error rate climbs.", a:[["m","dep","bad"],["s","cb","dep","call"],["s","dep","cb","timeout 2 s","x"],["m","cb","warn"],["n","cb","CLOSED · 45% errors"]]},
    {say:"Failures cross the threshold (50% over 20 calls). The breaker trips to OPEN.", a:[["s","dep","cb","timeout","x"],["m","cb","bad"],["n","cb","OPEN · 50% > threshold"]]},
    {say:"Open state: calls fail fast without touching the dependency. Checkout serves a fallback (last known prices) instead of hanging.", a:[["s","svc","cb","getPrice()"],["s","cb","fb","fail fast → fallback"],["s","fb","svc","cached price","r"],["n","svc","responds in 5 ms"]]},
    {say:"Failing fast protects both sides: your threads and connection pools stay free, and the struggling dependency gets breathing room to recover.", a:[["m","svc","ok"],["n","dep","no traffic · recovering"]]},
    {say:"After a cool-down timeout (30 s) the breaker moves to HALF-OPEN and lets a few trial requests through.", a:[["m","cb","warn"],["n","cb","HALF-OPEN · 3 trial calls"],["s","cb","dep","trial call"]]},
    {say:"The trials succeed, so the breaker closes and normal traffic resumes. Had a trial failed, it would go straight back to OPEN for another timeout.", a:[["m","dep","ok"],["s","dep","cb","200 · 35 ms","r"],["m","cb","ok"],["n","cb","CLOSED · reset counters"]]}
  ],
  takeaways:["Closed counts failures, open fails fast, half-open probes with a few trial calls.","Trip on error rate or slow-call rate over a window, not a single failure.","Always pair an open breaker with a fallback or a clear degraded response.","Retry only idempotent calls, with exponential backoff, jitter and a retry budget."],
  related:["sd-resilience-patterns"] },

{ id:"saga", group:"System Design Essentials", title:"Saga with transactional outbox", mode:"seq",
  blurb:"A choreographed order saga: atomic outbox writes, a relay that publishes, a failing step, compensations, and an idempotent consumer.",
  lanes:[{id:"ord",label:"Order service"},{id:"relay",label:"Outbox relay"},{id:"bus",label:"Broker"},{id:"pay",label:"Payment"},{id:"inv",label:"Inventory"}],
  steps:[
    {say:"Order service inserts the order row and an OrderCreated row into its outbox table in the same local transaction. Either both commit or neither does: no dual write.", a:[["m","ord","active"],["n","ord","BEGIN · orders + outbox · COMMIT"]]},
    {say:"The outbox relay polls the table (or tails the WAL with CDC) and publishes the event to the broker, then marks the row sent.", a:[["s","relay","ord","poll unsent outbox rows"],["s","ord","relay","OrderCreated #42","r"],["s","relay","bus","publish OrderCreated #42"]]},
    {say:"Payment consumes the event and charges the card in its own local transaction, then emits PaymentCompleted through its own outbox.", a:[["s","bus","pay","OrderCreated #42"],["n","pay","charge $80 · ok"],["m","pay","ok"],["s","pay","bus","PaymentCompleted #42"]]},
    {say:"Inventory tries to reserve stock, but the item is sold out. Its step fails and it emits ReservationFailed.", a:[["s","bus","inv","PaymentCompleted #42"],["m","inv","bad"],["n","inv","stock 0 · reserve failed"],["s","inv","bus","ReservationFailed #42","x"]]},
    {say:"There is no distributed rollback. Each earlier step runs a compensating action: Payment refunds the charge.", a:[["s","bus","pay","ReservationFailed #42"],["n","pay","refund $80 (compensation)"],["m","pay","warn"],["s","pay","bus","PaymentRefunded #42"]]},
    {say:"Order service compensates too: the order is marked cancelled and the customer is notified.", a:[["s","bus","ord","PaymentRefunded #42"],["n","ord","status = CANCELLED"],["m","ord","warn"]]},
    {say:"The relay crashed after publishing but before marking a row sent, so it publishes PaymentRefunded again. At-least-once delivery means duplicates will happen.", a:[["s","relay","bus","re-publish PaymentRefunded #42"],["s","bus","ord","PaymentRefunded #42 (dup)","x"]]},
    {say:"The consumer is idempotent: it records processed event ids in a table under a unique key, in the same transaction as its side effect. The duplicate is ignored.", a:[["n","ord","event id seen → skip"],["m","ord","ok"]]}
  ],
  takeaways:["A saga is a chain of local transactions with compensations instead of a distributed rollback.","The outbox pattern writes state and event in one transaction, avoiding dual writes.","Relays and brokers are at-least-once, so every consumer must be idempotent.","Compensations are business actions (refund, cancel), not undo; design them up front."],
  related:["sd-saga-outbox-idempotent-consumers","postgres-listen-notify-cdc"] },

{ id:"btree", group:"System Design Essentials", title:"B-tree index lookup", mode:"map",
  blurb:"Walk a B-tree from root to leaf for WHERE id = 4217, scan linked leaves for a range, compare heap fetches with index-only scans, and split a page.",
  nodes:[{id:"q",x:100,y:250,label:"Query",sub:"WHERE id = 4217",kind:"client"},{id:"root",x:340,y:90,label:"Root page",sub:"keys 3000 · 6000",kind:"db"},
         {id:"i1",x:260,y:250,label:"Internal page",sub:"1 – 2999",kind:"db"},{id:"i2",x:480,y:250,label:"Internal page",sub:"3000 – 5999",kind:"db"},
         {id:"l1",x:400,y:410,label:"Leaf page",sub:"4000 – 4299",kind:"db"},{id:"l2",x:620,y:410,label:"Leaf page",sub:"4300 – 4599",kind:"db"},
         {id:"heap",x:850,y:250,label:"Heap (table)",sub:"8 KB pages",kind:"db"},{id:"vm",x:850,y:90,label:"Visibility map",sub:"all-visible bits",kind:"service"}],
  edges:[["q","root"],["root","i1"],["root","i2"],["i2","l1"],["l1","l2"],["l1","heap"],["l2","heap"],["heap","vm"]],
  steps:[
    {say:"An index on id is a balanced tree of fixed-size pages. Every lookup starts at the root page, which is almost always in memory.", a:[["s","q","root","id = 4217"],["m","root","active"],["n","root","3000 ≤ 4217 < 6000"]]},
    {say:"The root's separator keys point to the internal page covering 3000–5999. Fan-out is hundreds of keys per page, so even a billion rows is only 3–4 levels deep.", a:[["s","root","i2","follow child 2"],["m","root",null],["m","i2","active"],["n","i2","→ leaf 4000–4299"]]},
    {say:"The internal page leads to the leaf that holds 4217. Leaves store the key plus a pointer to the row (a TID: heap page and slot).", a:[["s","i2","l1","descend"],["m","i2",null],["m","l1","active"],["n","l1","4217 → TID (812, 5)"]]},
    {say:"Index scan: fetch the row from the heap page the TID points to. That is one extra random read per matching row.", a:[["s","l1","heap","read page 812 slot 5"],["s","heap","q","row 4217","r"],["m","heap","ok"]]},
    {say:"Range scan WHERE id BETWEEN 4200 AND 4400: find the first leaf, then follow the sibling links rightwards. No need to go back up the tree.", a:[["m","heap",null],["s","l1","l2","next leaf →"],["m","l2","active"],["n","l2","4300 … 4400 · stop"]]},
    {say:"Index-only scan: if the index covers every selected column, the planner can skip the heap, but only for pages the visibility map marks all-visible. VACUUM keeps those bits set.", a:[["s","heap","vm","page 812 all-visible?"],["s","vm","heap","yes → skip heap","r"],["m","vm","ok"],["n","l1","Heap Fetches: 0"]]},
    {say:"Insert id = 4250 into a full leaf. There is no room, so the page splits: half the keys move to a new page and a new separator is pushed up into the parent.", a:[["m","vm",null],["m","l2",null],["s","q","l1","INSERT 4250"],["m","l1","warn"],["n","l1","full → split 4000–4149 | 4150–4299"],["s","l1","i2","push separator 4150"]]},
    {say:"Splits keep the tree balanced but cost write amplification and leave half-empty pages. Random keys (UUIDv4) split all over the tree; sequential keys only split the rightmost leaf.", a:[["m","l1","ok"],["m","i2","ok"],["n","i2","+1 separator · still balanced"]]}
  ],
  takeaways:["A B-tree lookup is O(log n) page reads; high fan-out keeps trees 3–4 levels deep.","Leaves are linked, so range scans and ORDER BY walk sideways without revisiting the root.","Index-only scans skip the heap only for all-visible pages, which VACUUM maintains.","Inserts can split pages; sequential keys split less and keep the index compact."],
  related:["postgres-indexing","mongodb-indexes-and-explain","postgres-explain-analyze"] },

{ id:"backpressure", group:"System Design Essentials", title:"Back-pressure in queues", mode:"map",
  blurb:"What happens when producers outpace consumers, and the levers you have: autoscaling, bounded queues, load shedding and dead-letter queues.",
  nodes:[{id:"p1",x:100,y:130,label:"Producer",sub:"checkout API",kind:"service"},{id:"p2",x:100,y:370,label:"Producer",sub:"batch import",kind:"service"},
         {id:"q",x:400,y:250,label:"Job queue",sub:"BullMQ · Redis",kind:"queue"},{id:"dlq",x:400,y:410,label:"Dead-letter queue",sub:"failed jobs",kind:"queue"},
         {id:"c1",x:640,y:130,label:"Consumer 1",sub:"worker",kind:"worker"},{id:"c2",x:640,y:370,label:"Consumer 2",sub:"worker",kind:"worker"},
         {id:"db",x:860,y:250,label:"Database",sub:"pool max 50",kind:"db"}],
  edges:[["p1","q"],["p2","q"],["q","c1"],["q","c2"],["q","dlq"],["c1","db"],["c2","db"]],
  steps:[
    {say:"Steady state: producers enqueue 500 jobs per second and two consumers process 500 per second. Queue depth stays near zero.", par:true, a:[["s","p1","q","enqueue · 300/s"],["s","q","c1","job"],["s","q","c2","job"],["n","q","depth 12"]]},
    {say:"A batch import starts. Producers now add 2,000 jobs per second, but consumers still finish 500. The queue absorbs the difference, for now.", par:true, a:[["s","p2","q","enqueue · 1700/s"],["s","p1","q","enqueue · 300/s"],["m","q","warn"],["n","q","depth +1500/s"]]},
    {say:"Depth and age of the oldest job keep growing. A lag alert fires: jobs are now waiting 4 minutes, and Redis memory is climbing.", a:[["m","q","bad"],["n","q","depth 360k · oldest 4 min"]]},
    {say:"Option 1, scale consumers out. This helps until the database becomes the bottleneck: consumers × concurrency must stay within the DB pool.", par:true, a:[["s","c1","db","INSERT"],["s","c2","db","INSERT"],["m","c1","active"],["m","c2","active"],["n","db","50/50 connections"],["m","db","warn"]]},
    {say:"Option 2, bound the queue and push back. When depth passes a limit, the API answers 429 and the import pauses its stream until the queue drains.", a:[["s","q","p2","full → pause stream","x"],["s","q","p1","429 · Retry-After","x"],["m","p2","warn"],["n","p2","paused"]]},
    {say:"Option 3, shed load by priority. Paid checkout jobs keep flowing on a high-priority queue; low-value work (thumbnails, analytics) is delayed or dropped.", a:[["m","p1","ok"],["s","p1","q","checkout · priority 1"],["n","q","drop/delay priority 3"]]},
    {say:"One malformed job crashes the worker on every attempt. After the retry limit it moves to the dead-letter queue so it stops blocking the line.", a:[["s","q","c1","job #9 (poison)"],["s","c1","q","fail × 5","x"],["s","q","dlq","move job #9"],["m","dlq","warn"],["n","dlq","inspect · fix · replay"]]},
    {say:"The import finishes, consumers catch up and the queue drains. Producers resume, and the extra consumers scale back in.", a:[["m","q","ok"],["n","q","depth 20 · oldest 1 s"],["m","db","ok"],["m","p2","ok"],["m","c1",null],["m","c2",null]]}
  ],
  takeaways:["A queue only buffers a rate mismatch; if producers stay faster, depth grows without bound.","Alert on queue depth and oldest-job age, not just consumer errors.","Scaling consumers is capped by downstream capacity such as the DB connection pool.","Bound queues and push back (429, pause), shed low-priority work, and dead-letter poison messages."],
  related:["mern-node-background-jobs-bullmq","sd-resilience-patterns","deploy-load-testing-k6-capacity"] },

{ id:"quorum", group:"System Design Essentials", title:"Quorum reads and writes (N, R, W)", mode:"map",
  blurb:"Three replicas, write quorum W=2 and read quorum R=2: a lagging replica, version numbers, read repair, and why R + W > N matters.",
  nodes:[{id:"cl",x:100,y:250,label:"Client",sub:"cart service",kind:"client"},{id:"co",x:380,y:250,label:"Coordinator",sub:"N=3 · W=2 · R=2",kind:"router"},
         {id:"r1",x:740,y:90,label:"Replica 1",sub:"zone a",kind:"db"},{id:"r2",x:740,y:250,label:"Replica 2",sub:"zone b",kind:"db"},
         {id:"r3",x:740,y:410,label:"Replica 3",sub:"zone c",kind:"db"}],
  edges:[["cl","co"],["co","r1"],["co","r2"],["co","r3"]],
  steps:[
    {say:"Each key is stored on N = 3 replicas. The client writes cart:42 and the coordinator sends the new value, tagged version 7, to all three at once.", par:true, a:[["s","cl","co","PUT cart:42"],["s","co","r1","write v7"],["s","co","r2","write v7"],["s","co","r3","write v7"],["m","co","active"]]},
    {say:"With W = 2 the coordinator only waits for two acks. Replicas 1 and 2 answer quickly, so the write succeeds even though replica 3 hasn't responded.", par:true, a:[["s","r1","co","ack v7","r"],["s","r2","co","ack v7","r"],["s","co","cl","200 · 2 of 3 acks","r"],["m","r1","ok"],["m","r2","ok"],["m","r3","warn"],["n","r3","lagging…"]]},
    {say:"Replica 3 crashes before applying the write. It still holds version 6. The system kept accepting writes because two of three replicas are enough.", a:[["m","r3","bad"],["n","r3","down · has v6"],["n","co","writes still OK (2/3)"]]},
    {say:"Replica 3 comes back. A read with R = 2 asks two replicas; here it happens to pick replica 2 and the stale replica 3.", par:true, a:[["m","r3","warn"],["n","r3","back · still v6"],["s","cl","co","GET cart:42"],["s","co","r2","read"],["s","co","r3","read"]]},
    {say:"The answers disagree. The coordinator compares version numbers (or vector clocks) and returns the newest one, v7. The client never sees the stale copy.", par:true, a:[["s","r2","co","v7","r"],["s","r3","co","v6","r"],["n","co","max(v7, v6) = v7"],["s","co","cl","cart v7","r"]]},
    {say:"Read repair: the coordinator writes v7 back to replica 3 in the background, so replicas converge without waiting for an anti-entropy sweep.", a:[["s","co","r3","repair → v7"],["m","r3","ok"],["n","r3","v7"]]},
    {say:"Why it works: R + W > N (2 + 2 > 3) means every read set overlaps every write set in at least one replica, so at least one answer carries the latest acknowledged write.", a:[["m","co","ok"],["n","co","R + W > N → overlap ≥ 1"]]},
    {say:"Now try R = 1, W = 1. A write of v8 is acknowledged by replica 1 alone, and the next read asks only replica 3.", a:[["n","co","N=3 · W=1 · R=1"],["s","co","r1","write v8"],["s","r1","co","ack","r"],["s","co","r3","read"],["s","r3","co","v7","x"],["m","co","bad"],["s","co","cl","stale v7","x"]]},
    {say:"R + W = 2 ≤ 3, so the sets need not overlap: lower latency and higher availability, but stale reads. Tune per workload: W = 3, R = 1 for read-heavy data; W = 1 for fire-and-forget metrics.", a:[["m","co","warn"],["n","co","fast but eventually consistent"],["n","r3","catches up later"]]}
  ],
  takeaways:["Data lives on N replicas; a write needs W acks and a read asks R replicas.","R + W > N guarantees read and write sets overlap, so reads see the latest acknowledged write.","Version numbers or vector clocks pick the newest answer; read repair fixes stale replicas.","Smaller R or W buys latency and availability at the cost of stale reads."],
  related:["sd-consistency-models","sd-design-key-value-store","sd-replication-strategies"] },

{ id:"raft", group:"System Design Essentials", title:"Raft leader election and log replication", mode:"map",
  blurb:"Five nodes: heartbeats, a leader crash, randomised election timeouts, votes by majority, committed log entries, and a minority partition that cannot make progress.",
  nodes:[{id:"n1",x:380,y:90,label:"Node 1",sub:"leader · term 1",kind:"server"},{id:"n2",x:720,y:90,label:"Node 2",sub:"follower",kind:"server"},
         {id:"n3",x:850,y:300,label:"Node 3",sub:"follower",kind:"server"},{id:"n4",x:560,y:410,label:"Node 4",sub:"follower",kind:"server"},
         {id:"n5",x:200,y:230,label:"Node 5",sub:"follower",kind:"server"},{id:"cl",x:110,y:410,label:"Client",sub:"config writes",kind:"client"}],
  edges:[["n1","n2"],["n1","n3"],["n1","n4"],["n1","n5"],["n2","n3"],["n2","n4"],["n2","n5"],["n3","n4"],["n3","n5"],["n4","n5"],["cl","n3"],["cl","n2"]],
  steps:[
    {say:"Node 1 is leader for term 1. It sends empty AppendEntries heartbeats to every follower, which resets their election timers.", par:true, a:[["m","n1","ok"],["n","n1","LEADER · term 1"],["s","n1","n2","heartbeat t1"],["s","n1","n3","heartbeat t1"],["s","n1","n4","heartbeat t1"],["s","n1","n5","heartbeat t1"]]},
    {say:"Node 1 crashes. Heartbeats stop. Each follower has a randomised election timeout (150–300 ms), so they won't all react at the same moment.", a:[["m","n1","bad"],["n","n1","crashed"],["n","n3","timer 160 ms"],["n","n5","timer 270 ms"]]},
    {say:"Node 3's timer fires first. It increments the term to 2, votes for itself, becomes a candidate and sends RequestVote to everyone.", par:true, a:[["m","n3","warn"],["n","n3","CANDIDATE · term 2"],["s","n3","n2","RequestVote t2"],["s","n3","n4","RequestVote t2"],["s","n3","n5","RequestVote t2"]]},
    {say:"Each node grants one vote per term, and only to a candidate whose log is at least as up to date as its own. Nodes 2 and 4 vote yes: 3 of 5 is a majority.", par:true, a:[["s","n2","n3","vote yes","r"],["s","n4","n3","vote yes","r"],["m","n3","ok"],["n","n3","LEADER · term 2 (3/5)"]]},
    {say:"The new leader immediately sends heartbeats so no one else starts an election. Node 5's vote request arrives late and is irrelevant.", par:true, a:[["s","n3","n2","heartbeat t2"],["s","n3","n4","heartbeat t2"],["s","n3","n5","heartbeat t2"],["n","n5","follower · term 2"]]},
    {say:"A client writes x = 5. Only the leader accepts writes. It appends the entry at log index 8 (uncommitted) and replicates it with AppendEntries.", par:true, a:[["s","cl","n3","SET x = 5"],["n","n3","log[8] x=5 · uncommitted"],["s","n3","n2","append [8]"],["s","n3","n4","append [8]"],["s","n3","n5","append [8]"]]},
    {say:"Nodes 2 and 4 persist the entry and ack. With the leader that is a majority, so index 8 is committed, applied to the state machine, and the client gets its answer.", par:true, a:[["s","n2","n3","ack [8]","r"],["s","n4","n3","ack [8]","r"],["n","n3","commitIndex = 8"],["s","n3","cl","OK · committed","r"],["m","cl","ok"]]},
    {say:"Node 1 restarts still believing it leads term 1. The first message it sees carries term 2, so it steps down to follower and the leader backfills its log.", a:[["m","n1","warn"],["s","n3","n1","heartbeat t2 + log [8]"],["n","n1","follower · term 2"],["m","n1",null]]},
    {say:"A partition splits {1, 2} from {3, 4, 5}. Node 2 stops hearing the leader, times out, and asks for votes, but only Node 1 can reach it: 2 of 5 is not a majority, so no leader and no commits on that side.", a:[["cut","n1","n3"],["cut","n1","n4"],["cut","n1","n5"],["cut","n2","n3"],["cut","n2","n4"],["cut","n2","n5"],["m","n2","warn"],["s","n2","n1","RequestVote t3"],["s","n1","n2","vote yes","r"],["n","n2","2/5 · no quorum"],["s","cl","n2","SET y = 1"],["s","n2","cl","unavailable","x"],["m","n1","bad"],["m","n2","bad"]]},
    {say:"The majority side keeps working: Node 3 commits with acks from 4 and 5. When the partition heals, 1 and 2 adopt the leader's log; Pre-Vote stops Node 2's inflated term from forcing a needless election.", a:[["s","n3","n4","append [9]"],["s","n4","n3","ack [9]","r"],["n","n3","commitIndex = 9"],["heal","n1","n3"],["heal","n1","n4"],["heal","n1","n5"],["heal","n2","n3"],["heal","n2","n4"],["heal","n2","n5"],["s","n3","n2","log [9]"],["m","n1","ok"],["m","n2","ok"]]}
  ],
  takeaways:["One leader per term; followers that stop hearing heartbeats start an election after a randomised timeout.","A candidate needs votes from a majority, and nodes only vote for candidates with an up-to-date log.","An entry is committed once a majority has stored it; only then does the client get success.","A minority partition can't elect a leader or commit, which is how Raft stays consistent (CP)."],
  related:["sd-distributed-coordination","sd-availability-reliability"] },

{ id:"geohash", group:"System Design Essentials", title:"Finding nearby drivers with geo cells", mode:"map",
  blurb:"Drivers stream locations into geohash cells, a rider request searches the cell and its neighbours, candidates are ranked by ETA, and an atomic assignment prevents double booking.",
  nodes:[{id:"rider",x:100,y:90,label:"Rider app",sub:"pickup 37.77,-122.42",kind:"client"},{id:"api",x:360,y:250,label:"Dispatch API",sub:"matching",kind:"server"},
         {id:"geo",x:620,y:90,label:"Geo index",sub:"Redis GEO",kind:"cache"},{id:"cells",x:860,y:90,label:"Geo cells",sub:"geohash · 1.2 km",kind:"service"},
         {id:"d3",x:860,y:250,label:"Driver C",sub:"available",kind:"client"},{id:"d1",x:620,y:410,label:"Driver A",sub:"available",kind:"client"},
         {id:"d2",x:860,y:410,label:"Driver B",sub:"available",kind:"client"},{id:"trips",x:100,y:410,label:"Trips DB",sub:"driver status",kind:"db"}],
  edges:[["rider","api"],["api","geo"],["geo","cells"],["api","d1"],["api","d2"],["api","d3"],["api","trips"]],
  steps:[
    {say:"Every available driver's app sends its position every 4 seconds. That is a firehose of writes: 500k drivers means about 125k updates per second.", par:true, a:[["s","d1","api","loc · 4 s"],["s","d2","api","loc · 4 s"],["s","d3","api","loc · 4 s"],["m","api","active"]]},
    {say:"The API files each driver under the geohash cell of its position. Nearby points share a cell prefix, so a 2-D lookup becomes a key lookup.", a:[["s","api","geo","GEOADD drivers A, B, C"],["s","geo","cells","bucket by geohash"],["n","cells","9q8yy: A, C · 9q8yz: B"]]},
    {say:"Locations go stale fast. Each driver entry carries a last-seen timestamp; drivers silent for 30 s are dropped from the available set.", a:[["n","geo","last-seen ≤ 30 s"],["m","geo","ok"]]},
    {say:"A rider requests a car. The API computes the geohash of the pickup point: cell 9q8yy.", a:[["s","rider","api","request ride"],["n","api","pickup → cell 9q8yy"]]},
    {say:"A nearby driver can sit just across a cell border, so the search covers the cell plus its 8 neighbours (GEOSEARCH with a radius does the same).", a:[["s","api","geo","GEOSEARCH r = 2 km"],["s","geo","cells","9q8yy + 8 neighbours"],["s","cells","geo","A, B, C","r"],["s","geo","api","3 candidates","r"]]},
    {say:"Straight-line distance misleads (rivers, one-way streets). Candidates are re-ranked by road ETA from a routing service.", a:[["n","api","C 2 min · A 4 min · B 6 min"]]},
    {say:"The best driver gets an offer with a 15-second timeout. Driver C doesn't respond, so the offer lapses and moves to the next candidate.", a:[["s","api","d3","offer · 15 s"],["m","d3","warn"],["n","d3","no response"],["s","d3","api","timeout","x"]]},
    {say:"Driver A accepts. Another rider's dispatch may be offering A at the same moment, so assignment must be atomic.", a:[["s","api","d1","offer · 15 s"],["s","d1","api","accept","r"],["m","d1","active"]]},
    {say:"A conditional update flips A to on_trip only if A is still available. Exactly one dispatcher sees 1 row updated; the other sees 0 and tries its next candidate.", a:[["s","api","trips","UPDATE … WHERE available"],["s","trips","api","1 row · assigned","r"],["n","trips","second dispatcher: 0 rows"],["m","trips","ok"]]},
    {say:"A is removed from the available index and the rider sees the match. A's location stream now feeds the live trip map instead.", a:[["s","api","geo","ZREM drivers A"],["s","api","rider","Driver A · 4 min","r"],["m","d1","ok"],["n","d1","on_trip"],["m","rider","ok"]]}
  ],
  takeaways:["Geohash (or S2/H3) cells turn 'nearby' into a prefix or key lookup.","Always search the cell plus its neighbours to catch drivers just across a border.","Rank candidates by road ETA, and offer to one driver at a time with a timeout.","Assign with an atomic conditional update so two riders can never get the same driver."],
  related:["sd-geospatial-indexing","sd-design-ride-sharing"] },

{ id:"chatdelivery", group:"System Design Essentials", title:"Chat message delivery and receipts", mode:"seq",
  blurb:"One message from send to read: client ids for dedupe, per-conversation sequence numbers, sent, delivered and read ticks, plus the offline path via push and sync.",
  lanes:[{id:"snd",label:"Sender app"},{id:"gwa",label:"WS gateway A"},{id:"chat",label:"Chat service"},{id:"store",label:"Message store"},
         {id:"gwb",label:"WS gateway B"},{id:"rcp",label:"Recipient app"},{id:"push",label:"Push service"}],
  steps:[
    {say:"Alice sends a message over her WebSocket. The app generates a client message id first, so a retry after a dropped connection can be recognised as the same message.", a:[["n","snd","clientId c-91 · ⏱ pending"],["s","snd","gwa","send {clientId c-91}"],["s","gwa","chat","forward"]]},
    {say:"The chat service persists the message and assigns the next sequence number for the conversation. A unique key on clientId makes the insert idempotent.", a:[["s","chat","store","INSERT · seq = 1042"],["s","store","chat","stored","r"],["m","store","ok"]]},
    {say:"Only after it is durable does the server ack the sender. Alice's app shows a single tick: sent.", a:[["s","chat","gwa","ack c-91 → 1042","r"],["s","gwa","snd","ack seq 1042","r"],["n","snd","✓ sent"],["m","snd","ok"]]},
    {say:"Which gateway holds Bob's socket? The service looks him up in the connection registry (Redis: user → gateway, refreshed by heartbeats).", a:[["n","chat","registry: bob → gateway B"],["m","chat","active"]]},
    {say:"Gateway B pushes the message down Bob's socket. Bob's app acks receipt, and the delivered receipt flows back to Alice: double tick.", a:[["s","chat","gwb","deliver 1042"],["s","gwb","rcp","msg 1042"],["s","rcp","gwb","delivered 1042","r"],["s","gwb","chat","delivered","r"],["s","chat","gwa","receipt: delivered","r"],["s","gwa","snd","✓✓ delivered","r"]]},
    {say:"Bob opens the chat. A read receipt carries the highest sequence read, so one event covers many messages, and the store records his read cursor.", a:[["s","rcp","gwb","read up to 1042"],["s","gwb","chat","read 1042"],["s","chat","store","last_read[bob] = 1042"],["s","chat","gwa","receipt: read","r"],["s","gwa","snd","✓✓ read","r"],["m","rcp","ok"]]},
    {say:"Later Bob is offline. The registry has no live connection, so the message is stored as usual and the push service sends a notification via APNs or FCM.", a:[["m","rcp","warn"],["n","rcp","offline"],["s","chat","store","INSERT · seq 1043–1047"],["n","chat","registry: bob → none"],["s","chat","push","notify bob"],["s","push","rcp","APNs/FCM: 5 new messages"]]},
    {say:"Bob reconnects and tells the server the last sequence he has. The server returns everything after it, in order, with no gaps and no duplicates.", a:[["s","rcp","gwb","connect · last seq 1042"],["s","gwb","chat","sync since 1042"],["s","chat","store","seq > 1042"],["s","store","chat","1043–1047","r"],["s","chat","gwb","batch","r"],["s","gwb","rcp","1043–1047","r"],["m","rcp","ok"]]},
    {say:"If Alice's ack was lost and she resends c-91, the unique clientId returns the existing seq 1042 instead of creating a duplicate message.", a:[["s","snd","gwa","resend c-91","x"],["s","gwa","chat","forward"],["n","chat","c-91 exists → seq 1042"],["s","chat","gwa","ack 1042 (dedup)","r"],["s","gwa","snd","ack 1042","r"]]}
  ],
  takeaways:["Persist before acking: the single tick means the message is durable on the server.","Per-conversation sequence numbers give ordering and let clients sync from their last seen seq.","A connection registry routes messages to the gateway holding the recipient's socket.","Client message ids make resends idempotent; offline users get push plus sync on reconnect."],
  related:["sd-design-chat-system","mern-arch-realtime-socketio"] },

{ id:"seathold", group:"System Design Essentials", title:"Ticket booking: seat holds under contention", mode:"seq",
  blurb:"Two users race for seat 14C: a conditional UPDATE picks exactly one winner, the loser gets 409, the winner pays inside a 10-minute hold, and a sweeper releases abandoned holds.",
  lanes:[{id:"ua",label:"User A"},{id:"ub",label:"User B"},{id:"api",label:"Booking API"},{id:"db",label:"Inventory DB"},{id:"pay",label:"Payment"}],
  steps:[
    {say:"The show goes on sale and two users tap seat 14C within the same millisecond.", par:true, a:[["s","ua","api","hold 14C"],["s","ub","api","hold 14C"],["m","api","active"]]},
    {say:"Checking then updating would race. Instead the API issues one conditional update, UPDATE seats SET status='held' WHERE id='14C' AND status='available', which only changes the row if the seat is still free. A's statement lands first.", a:[["s","api","db","UPDATE … WHERE available (A)"],["s","db","api","1 row (A)","r"],["m","db","ok"]]},
    {say:"B's identical statement now matches zero rows, because the status is already 'held'. No lock juggling, no double booking: B gets 409 Conflict and picks another seat.", a:[["s","api","db","same UPDATE for B"],["s","db","api","0 rows","x"],["s","api","ub","409 · seat taken","x"],["m","ub","warn"]]},
    {say:"A's hold stores held_by = A and hold_until = now() + 10 minutes. The UI shows a countdown.", a:[["s","api","ua","held until 12:10","r"],["n","ua","⏱ 9:59 left"],["n","db","14C held · A · until 12:10"]]},
    {say:"A pays. The charge carries an idempotency key, so a retried request can't charge twice.", a:[["s","ua","api","pay"],["s","api","pay","charge · Idempotency-Key h-77"],["s","pay","api","succeeded","r"]]},
    {say:"The seat is confirmed with another conditional update: only if A still holds it and the hold hasn't expired.", a:[["s","api","db","SET booked WHERE held_by=A"],["n","db","… AND hold_until > now()"],["s","db","api","1 row","r"],["s","api","ua","confirmed · 14C","r"],["m","ua","ok"],["n","db","14C booked"]]},
    {say:"Rewind to the alternate path: A walked away without paying. At 12:10 the hold expires.", a:[["m","ua","warn"],["n","ua","tab closed"],["n","db","14C held · expired 12:10"],["m","db","warn"]]},
    {say:"A sweeper job runs every minute and releases expired holds back to available. Reads can also treat expired holds as free, so the seat reappears instantly.", a:[["s","api","db","release expired holds"],["n","db","WHERE hold_until < now()"],["s","db","api","1 row released","r"],["n","api","sweeper · every 60 s"],["m","db","ok"]]},
    {say:"B tries 14C again and wins the conditional update this time. If A's late payment ever lands, the confirm update matches 0 rows and A is refunded automatically.", a:[["s","ub","api","hold 14C"],["s","api","db","UPDATE … WHERE available (B)"],["s","db","api","1 row (B)","r"],["s","api","ub","held until 12:21","r"],["m","ub","ok"],["n","pay","late A charge → refund"]]}
  ],
  takeaways:["A conditional UPDATE … WHERE status='available' is an atomic compare-and-set: exactly one winner.","The loser gets a fast 409 instead of waiting on locks.","Holds have an expiry; a sweeper (or expiry-aware reads) returns abandoned seats to inventory.","Confirm with a second conditional update and idempotent payments so late or retried payments are safe."],
  related:["sd-design-ticket-booking","postgres-locking-deadlocks"] },

{ id:"youtube", group:"System Design Essentials", title:"YouTube end to end", mode:"map",
  blurb:"One video's whole life: presigned upload, the transcoding DAG, publish and notify, a cached watch page, CDN segments with ABR, likes and comments through Kafka with batched counters, view heartbeats, and a live stream.",
  nodes:[{id:"creator",x:90,y:90,label:"Creator",sub:"studio · OBS",kind:"user"},{id:"viewer",x:90,y:390,label:"Viewer",sub:"web · app · TV",kind:"client"},
         {id:"obj",x:380,y:130,label:"Object storage",sub:"originals · segments",kind:"db"},{id:"proc",x:640,y:70,label:"Media pipeline",sub:"transcode · live",kind:"worker"},
         {id:"kafka",x:860,y:90,label:"Kafka",sub:"event bus",kind:"queue"},{id:"gw",x:480,y:250,label:"API gateway",sub:"auth · BFF",kind:"gateway"},
         {id:"cdn",x:240,y:250,label:"CDN",sub:"ISP cache · edge",kind:"cdn"},{id:"redis",x:400,y:410,label:"Redis",sub:"cache · counters",kind:"cache"},
         {id:"meta",x:680,y:410,label:"Metadata DB",sub:"videos · reactions",kind:"db"}],
  edges:[["creator","gw"],["creator","obj"],["creator","proc"],["gw","kafka"],["kafka","proc"],["proc","obj"],["proc","meta"],["gw","meta"],
         ["gw","redis"],["redis","meta"],["kafka","redis"],["viewer","gw"],["viewer","cdn"],["cdn","obj"]],
  steps:[
    {say:"A creator starts a 4 GB upload. The API only creates an upload session and hands back presigned URLs; it never touches video bytes.", a:[["s","creator","gw","POST /uploads · 4 GB"],["s","gw","meta","insert upload session"],["s","gw","creator","256 presigned part URLs","r"],["m","creator","active"]]},
    {say:"The app uploads 16 MB parts straight to object storage, several in parallel, retrying failed parts individually. On complete, the video row becomes processing and video.uploaded goes onto Kafka; the heavy work is asynchronous.", a:[["s","creator","obj","PUT parts 1–256"],["n","obj","original · 4 GB"],["s","creator","gw","POST complete"],["s","gw","meta","status = processing"],["s","gw","kafka","video.uploaded"],["m","creator",null],["n","meta","v123 · processing"]]},
    {say:"The media pipeline runs a DAG: split at keyframes, encode every chunk at every rung in parallel, plus audio, thumbnails, captions, Content ID and safety checks. 360p and 720p come first so the video is playable in minutes.", a:[["s","kafka","proc","start workflow v123"],["m","proc","active"],["s","proc","obj","read original"],["n","proc","720 chunks × 12 rungs"],["s","proc","obj","CMAF segments + HLS/DASH"]]},
    {say:"Checks pass, so the status flips to ready with a conditional update, and video.published fans out: search indexing, recommendations, and notifications to subscribers.", a:[["s","proc","meta","ready WHERE processing"],["n","meta","v123 · ready"],["s","proc","kafka","video.published"],["n","kafka","→ index · recs · notify subs"],["m","proc","ok"],["m","meta","ok"]]},
    {say:"A viewer opens the watch page. The BFF reads metadata and counts from Redis (a 2 ms hit for popular videos) and returns the page with a signed manifest URL.", a:[["m","proc",null],["m","meta",null],["s","viewer","gw","GET /watch/v123"],["s","gw","redis","metadata + counts"],["s","redis","gw","hit · 2 ms","r"],["s","gw","viewer","page + signed manifest","r"],["m","viewer","active"]]},
    {say:"The player fetches the manifest and the first segment from the CDN hostname DNS picked for it. A miss on this new video goes through the origin shield to object storage once, then stays cached.", a:[["s","viewer","cdn","GET seg_1 · 360p"],["m","cdn","warn"],["s","cdn","obj","miss → shield → origin"],["s","obj","cdn","segment","r"],["s","cdn","viewer","first frame · 0.8 s","r"],["m","cdn","ok"]]},
    {say:"Adaptive bitrate: before each segment the player picks a rendition from measured throughput and buffer level. Segments are immutable, so later requests are edge or ISP-cache hits.", a:[["s","viewer","cdn","seg_2…n · 1080p"],["s","cdn","viewer","HIT · 12 ms","r"],["n","viewer","ABR 360p → 1080p · buffer 30 s"],["m","viewer","ok"]]},
    {say:"The viewer likes the video. The UI shows +1 at once. The API sets the final state (LIKE) on the (video, user) row, so a retry adds nothing, and publishes a +1 delta.", a:[["m","viewer",null],["s","viewer","gw","PUT reaction LIKE"],["s","gw","meta","upsert (v123, u7) = LIKE"],["s","gw","kafka","delta likes +1"],["n","gw","retry → same state · no delta"]]},
    {say:"A counter consumer sums deltas for a second and does one INCRBY on a random counter shard. Twenty thousand likes a second on a viral video become a few writes; totals flush to the DB every 20 s.", a:[["s","kafka","redis","Σ 1 s · INCRBY shard 17"],["n","redis","likes 1.2M"],["s","redis","meta","flush every 20 s"],["m","redis","ok"]]},
    {say:"A comment passes fast synchronous checks (blocked words, a light spam model) and is stored as visible. An async toxicity model scores it from Kafka and can hold it for review.", a:[["s","viewer","gw","POST comment"],["n","gw","sync spam check ✓"],["s","gw","meta","insert · visible"],["s","gw","kafka","comment.created"],["n","kafka","async model → hold if risky"]]},
    {say:"While watching, the player sends heartbeats every 30 s. A stream job dedupes and filters bots, then writes per-minute view counts; the warehouse later produces the verified number.", a:[["s","viewer","gw","heartbeats · 30 s"],["s","gw","kafka","views topic"],["s","kafka","redis","deduped views / min"],["n","kafka","2.8 M events/s at peak"]]},
    {say:"Live is the same shape, faster: OBS pushes RTMPS to ingest near the creator, the pipeline transcodes in real time into 2 s CMAF chunks, and the CDN collapses millions of requests for each new chunk into one.", a:[["s","creator","proc","RTMPS live ingest"],["m","proc","active"],["s","proc","obj","LL-HLS chunks · 2 s"],["s","obj","cdn","live segment","r"],["s","cdn","viewer","2–5 s behind live","r"],["m","proc","ok"],["m","viewer","ok"]]}
  ],
  takeaways:["Video bytes never pass through the API: upload to object storage with presigned URLs and serve segments from the CDN.","Transcoding is an async, event-triggered DAG; a fast 360p/720p path makes videos playable in minutes.","Reads come from caches: metadata in Redis, segments at the edge, with ABR choosing a rendition per segment.","Likes, comments and views write a small durable record, then flow through Kafka so counts are batched, sharded and eventually consistent."],
  related:["sd-design-youtube-complete","sd-design-video-streaming","sd-design-chat-system","sd-caching-strategies"] },

/* ---------------- Database Design ---------------- */
{ id:"normalize", group:"Database Design", title:"Normalising a messy orders table", mode:"map",
  blurb:"One wide orders table repeats customer and product data. Watch the update, insert and delete anomalies, then split it step by step through 1NF, 2NF and 3NF and join it back together.",
  nodes:[{id:"app",x:100,y:250,label:"App",sub:"order service",kind:"client"},{id:"flat",x:340,y:250,label:"orders_flat",sub:"one wide table",kind:"db"},
         {id:"cust",x:620,y:80,label:"customers",sub:"id · name · email",kind:"db"},{id:"prod",x:860,y:110,label:"products",sub:"id · name · price",kind:"db"},
         {id:"ord",x:620,y:250,label:"orders",sub:"id · customer_id · date",kind:"db"},{id:"items",x:620,y:410,label:"order_items",sub:"order · product · qty",kind:"db"},
         {id:"view",x:860,y:380,label:"Order view",sub:"JOIN result",kind:"service"}],
  edges:[["app","flat"],["app","cust"],["flat","cust"],["flat","prod"],["flat","ord"],["flat","items"],["cust","ord"],["ord","items"],["prod","items"],["ord","view"],["items","view"]],
  steps:[
    {say:"The first version of the shop stores everything in one table: order_id, order_date, customer_name, customer_email, and a products column holding 'mug x2, tee x1'. Every order copies the customer's details and every product's name and price.", a:[["s","app","flat","INSERT order #1001"],["m","flat","active"],["n","flat","customer + product data per row"]]},
    {say:"First normal form: one atomic value per cell and no repeating groups. The comma list becomes one row per order line, with the key (order_id, product_id). Now you can query and index products, but the duplication is worse.", a:[["n","flat","1NF · key (order_id, product_id)"],["m","flat","warn"]]},
    {say:"Update anomaly: Ann changes her email. UPDATE orders_flat SET customer_email = 'ann@new.io' WHERE order_id = 1001 touches only that order's rows. Her other eleven rows still say ann@old.io, and the data now contradicts itself.", a:[["s","app","flat","UPDATE email · 1 order only","x"],["m","flat","bad"],["n","flat","ann@old ×11 · ann@new ×1"]]},
    {say:"Insert anomaly: the shop adds a lamp that nobody has bought yet. There is no order_id to put in the key, so the product can't be stored without inventing a fake order.", a:[["s","app","flat","INSERT lamp · no order","x"],["n","flat","PK needs order_id → rejected"]]},
    {say:"Delete anomaly: the only order containing the vase is cancelled. Deleting its rows also deletes the only record of the vase's name and price.", a:[["s","app","flat","DELETE order #1007","x"],["n","flat","vase product info gone"]]},
    {say:"Second normal form: every non-key column must depend on the whole key. product_name and price depend only on product_id, and order_date and the customer columns depend only on order_id. Those partial dependencies move to products and orders; order_items keeps (order_id, product_id, quantity).", a:[["m","flat",null],["s","flat","prod","move product columns"],["s","flat","ord","move order columns"],["s","flat","items","keep order lines"],["m","prod","ok"],["m","items","ok"],["n","flat","split → 3 tables"]]},
    {say:"Third normal form: no non-key column may depend on another non-key column. In orders, customer_name and customer_email depend on customer_id, not on the order id. They move to customers, and orders keeps only the customer_id foreign key.", a:[["s","ord","cust","move customer columns"],["n","ord","customer_id FK only"],["m","ord","ok"],["m","cust","ok"]]},
    {say:"The anomalies are gone. Ann's email lives in exactly one row, a product can exist with no orders, and cancelling an order leaves the product catalogue untouched.", a:[["s","app","cust","UPDATE email · 1 row","r"],["n","cust","ann@new.io · single source"],["n","flat","retired"]]},
    {say:"One column is duplicated on purpose. order_items.unit_price is copied from products.price at checkout. When the mug goes from 20 to 25, old orders must still show what the customer actually paid. It is a fact about the sale, not a copy of the product, so it doesn't break 3NF.", a:[["s","prod","items","copy price at checkout"],["n","prod","mug price now 25"],["n","items","unit_price 20 · snapshot"]]},
    {say:"Reads put the wide view back together with joins: SELECT o.id, c.email, p.name, i.quantity, i.unit_price FROM orders o JOIN customers c ON c.id = o.customer_id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id. Foreign keys plus indexes on order_items(order_id) keep this fast.", a:[["s","ord","view","orders ⋈ customers"],["s","items","view","order_items ⋈ products"],["m","view","ok"],["n","view","same rows · one copy each"]]}
  ],
  takeaways:["Duplicated facts cause update, insert and delete anomalies.","1NF: atomic values; 2NF: no partial dependency on part of a composite key; 3NF: no dependency between non-key columns.","Joins over foreign keys rebuild the wide view, so normalised tables lose nothing.","Historical snapshots like order_items.unit_price are intentional facts, not denormalisation mistakes."],
  related:["dbd-normalization","dbd-er-modeling-relationships","dbd-how-to-design-a-database-schema"] },

{ id:"lsm", group:"Database Design", title:"LSM tree write and read path", mode:"map",
  blurb:"Writes append to a WAL and a sorted memtable, flush to immutable SSTables and compact into deeper levels; reads check the memtable, then use bloom filters to skip SSTables. Compared with a B-tree's in-place updates.",
  nodes:[{id:"cl",x:100,y:250,label:"Client",sub:"PUT · GET",kind:"client"},{id:"wal",x:360,y:90,label:"WAL",sub:"append-only log",kind:"db"},
         {id:"mem",x:360,y:250,label:"Memtable",sub:"sorted · in memory",kind:"cache"},{id:"bloom",x:360,y:410,label:"Bloom filters",sub:"one per SSTable",kind:"service"},
         {id:"l0",x:640,y:250,label:"SSTable L0",sub:"immutable · overlapping",kind:"db"},{id:"l1",x:860,y:250,label:"Level L1",sub:"merged · non-overlapping",kind:"db"},
         {id:"bt",x:640,y:410,label:"B-tree page",sub:"update in place",kind:"db"}],
  edges:[["cl","wal"],["cl","mem"],["mem","l0"],["l0","l1"],["cl","bloom"],["bloom","l0"],["bloom","l1"],["cl","bt"]],
  steps:[
    {say:"PUT user:42. The write is first appended to the write-ahead log and fsynced. Appending is sequential I/O, the cheapest thing a disk can do, and it is what makes the write durable.", a:[["s","cl","wal","append PUT user:42"],["m","wal","active"],["n","wal","sequential · fsync"]]},
    {say:"Then the key goes into the memtable, a sorted in-memory structure such as a skip list, and the client gets its ack. No page on disk was read or rewritten.", a:[["m","wal",null],["s","cl","mem","insert user:42 = v3"],["s","mem","cl","ack","r"],["m","mem","active"]]},
    {say:"A delete doesn't remove anything. It writes a tombstone, a marker that says user:17 is gone, which shadows older values in older files until compaction cleans up.", a:[["s","cl","wal","append DEL user:17"],["s","cl","mem","user:17 = tombstone"],["n","mem","64 MB · full"],["m","mem","warn"]]},
    {say:"When the memtable fills, it is frozen and written out as an SSTable: a sorted, immutable file with a sparse index and a bloom filter. A fresh memtable takes new writes, and the WAL segment it covered can be deleted.", a:[["s","mem","l0","flush sorted run"],["m","mem",null],["n","mem","fresh memtable"],["n","wal","old segment dropped"],["n","l0","4 SSTables · keys overlap"],["m","l0","warn"]]},
    {say:"Background compaction merge-sorts L0 files into L1. For each key only the newest version survives, and once a tombstone reaches the bottom level the deleted key and the tombstone are both dropped. Rewriting data like this is the LSM's write amplification.", a:[["s","l0","l1","merge-sort compaction"],["m","l0",null],["n","l0","empty"],["n","l1","user:17 + tombstone dropped"],["m","l1","ok"]]},
    {say:"GET user:42. The newest data is in memory, so the memtable is checked first. Here it misses: the key was flushed earlier.", a:[["s","cl","mem","GET user:42"],["s","mem","cl","not in memtable","r"]]},
    {say:"Without help, a read would have to search every SSTable, newest first. Each SSTable's bloom filter answers 'definitely not here' or 'maybe here' from a few bits in memory. Every L0 file says no, so none of them is read.", a:[["s","cl","bloom","which SSTables may hold it?"],["m","bloom","active"],["s","bloom","l0","skip all · bloom says no","x"],["n","bloom","~1% false positives"]]},
    {say:"L1's filter says maybe. Its sparse index points to one 4 KB block, a single disk read finds user:42 = v3, and the value goes back to the client.", a:[["s","bloom","l1","read 1 block"],["s","l1","bloom","user:42 = v3","r"],["s","bloom","cl","v3","r"],["m","bloom",null],["m","cl","ok"]]},
    {say:"Compare a B-tree: UPDATE finds the leaf page holding the key and rewrites it in place, after logging the change to its own WAL. Each key lives in exactly one place, so reads are fast and predictable, but every write is a random page write. LSM trees trade read and space amplification for cheap sequential writes, which suits write-heavy stores like Cassandra, RocksDB and ScyllaDB.", a:[["s","cl","bt","UPDATE page 812 in place"],["m","bt","active"],["n","bt","random write · 1 copy per key"],["n","l1","LSM: sequential writes"]]}
  ],
  takeaways:["Writes go to an append-only WAL and a sorted memtable, so they never rewrite pages on disk.","Full memtables flush to immutable SSTables; compaction merges levels and drops overwritten values and tombstones.","Reads check the memtable first, then use bloom filters to skip SSTables that can't contain the key.","B-trees update in place and favour reads; LSM trees favour writes at the cost of read, write and space amplification."],
  related:["dbd-storage-engines-btree-vs-lsm","dbd-indexing-fundamentals","sd-design-key-value-store"] },

{ id:"optlock", group:"Database Design", title:"Lost update vs optimistic locking", mode:"seq",
  blurb:"Alice and Bob both read stock 10 and write back blindly, losing a sale. A version column turns the write into a compare-and-set, Bob retries, and an atomic decrement removes the read entirely.",
  lanes:[{id:"al",label:"Alice"},{id:"bo",label:"Bob"},{id:"api",label:"API"},{id:"db",label:"Database"}],
  steps:[
    {say:"Alice and Bob open product 55 at the same moment. Both reads return stock 10 and version 7.", a:[["s","al","api","GET /products/55"],["s","bo","api","GET /products/55"],["s","api","db","SELECT stock, version"],["s","db","api","stock 10 · v7","r"],["s","api","al","stock 10 · v7","r"],["s","api","bo","stock 10 · v7","r"]]},
    {say:"Alice buys one. The API computes 10 − 1 in application code and writes UPDATE products SET stock = 9 WHERE id = 55.", a:[["s","al","api","buy 1"],["s","api","db","SET stock = 9"],["s","db","api","1 row","r"],["s","api","al","200 · ordered","r"]]},
    {say:"Bob buys two, but his API call computed from the stale read: UPDATE products SET stock = 8 WHERE id = 55. It succeeds too. Three units are sold yet stock says 8: Alice's write was silently overwritten. Read committed, the default in Postgres, does nothing to stop this.", a:[["s","bo","api","buy 2"],["s","api","db","SET stock = 8"],["s","db","api","1 row","r"],["s","api","bo","200 · ordered","r"],["n","db","stock 8 · should be 7"],["m","db","bad"]]},
    {say:"Rewind and add a version column. Both users read the same row again: stock 10, version 7. The version they read travels with their write.", a:[["m","db",null],["n","db","reset · stock 10 · v7"],["n","api","remember version 7"]]},
    {say:"Alice's write becomes a compare-and-set: UPDATE products SET stock = 9, version = 8 WHERE id = 55 AND version = 7. The row still has version 7, so one row changes and the version moves to 8.", a:[["s","al","api","buy 1 · read v7"],["s","api","db","SET 9, v8 WHERE v = 7"],["s","db","api","1 row · now v8","r"],["s","api","al","200 · ordered","r"],["m","al","ok"]]},
    {say:"Bob's write carries the same condition: UPDATE products SET stock = 8, version = 8 WHERE id = 55 AND version = 7. The version is already 8, so it matches zero rows. Nothing is overwritten, and the API knows there was a conflict.", a:[["s","bo","api","buy 2 · read v7"],["s","api","db","SET 8, v8 WHERE v = 7"],["s","db","api","0 rows","x"],["n","api","conflict → retry"],["m","bo","warn"]]},
    {say:"The API re-reads the row, recomputes from fresh data and tries again with the new version: SET stock = 7, version = 9 WHERE id = 55 AND version = 8. It succeeds. Retries are bounded; for a form a human edited, return 409 and let them review instead.", a:[["s","api","db","re-read product 55"],["s","db","api","stock 9 · v8","r"],["s","api","db","SET 7, v9 WHERE v = 8"],["s","db","api","1 row · now v9","r"],["s","api","bo","200 · ordered","r"],["m","bo","ok"],["n","db","stock 7 · v9 ✓"],["m","db","ok"]]},
    {say:"When the change is plain arithmetic, skip the read entirely: UPDATE products SET stock = stock - 1 WHERE id = 55 AND stock >= 1 RETURNING stock. The database applies each decrement atomically under the row lock, and the WHERE clause refuses to oversell: 0 rows means sold out.", a:[["s","al","api","buy 1"],["s","api","db","stock = stock - 1 (Alice)"],["s","db","api","1 row · stock 9","r"],["s","bo","api","buy 2"],["s","api","db","stock = stock - 2 (Bob)"],["s","db","api","1 row · stock 7","r"],["n","db","WHERE stock >= n · no oversell"]]}
  ],
  takeaways:["Read, compute in the app, then write back blindly loses concurrent updates, even inside transactions at read committed.","Optimistic locking adds WHERE version = ? to the UPDATE; 0 rows affected means someone else won.","On conflict, re-read and retry a bounded number of times, or return 409 for human edits.","For simple counters an atomic UPDATE stock = stock - n WHERE stock >= n is simpler and needs no version."],
  related:["dbd-concurrency-patterns","dbd-transactions-acid-isolation","postgres-transactions-isolation"] }
];
